  return <div className="page people-page"><PageHeader eyebrow="Personal CRM" title="Contacts" subtitle="Relevant relationships first. Automated and unclassified senders are kept in separate sections." /><div className="summary-bar"><div className="summary-stat"><strong>{items.filter((person) => isRelevantContact(person) && visibleEntityType(person) === "person").length}</strong><span>relevant contacts</span></div><div className="summary-stat"><strong>{highPriority}</strong><span>high priority</span></div><div className="summary-stat"><strong>{openLoops}</strong><span>open follow-ups</span></div></div><div className="people-layout"><section className="people-list"><select className="filter" aria-label="Contact directory section" value={contactView} onChange={(event) => setContactView(event.target.value as typeof contactView)}><option value="relevant">Relevant contacts</option><option value="people">Confirmed people</option><option value="organizations">Organizations</option><option value="automated">Automated senders</option><option value="review">Needs review</option><option value="all">All contacts</option></select><input className="people-search" aria-label="Search people" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search name, company or email…" />{filtered.length === 0 ? <div className="empty-card">No people match your search.</div> : filtered.map((person) => <button className={`person-row ${selected?.id === person.id ? "selected" : ""}`} key={person.id} onClick={() => choose(person)}><div className="avatar">{person.name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase()}</div><div><strong>{person.name}</strong><small>{person.organization || person.relationshipType}</small></div><div className="person-row-meta"><span>{person.conversations.length}</span><small>conversations</small></div></button>)}</section>{selected ? <section className="person-detail"><div className="person-detail-head"><div className="avatar">{selected.name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase()}</div><div><h2>{selected.name}</h2><span>{selected.identities.map((identity) => identity.source).filter((value, index, values) => values.indexOf(value) === index).join(" · ") || "Manual contact"}</span></div>{selected.lastContactAt && <small>Last contact {new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(selected.lastContactAt))}</small>}</div><div className="person-metrics"><div><strong>{selected.conversations.length}</strong><span>conversations</span></div><div><strong>{selected.memories.length}</strong><span>verified memories</span></div><div><strong>{selected.openLoops}</strong><span>open follow-ups</span></div><div><strong>{selected.responseRate == null ? "—" : `${selected.responseRate}%`}</strong><span>response coverage</span></div></div><div className="person-detail-grid"><div className="person-editor"><div className="section-title">Your verified information</div><label>Name<input value={editor.name} onChange={(event) => setEditor((value) => ({ ...value, name: event.target.value }))} /></label><label>Organization<input value={editor.organization} onChange={(event) => setEditor((value) => ({ ...value, organization: event.target.value }))} /></label><label>Contact type<select value={editor.entityType} onChange={(event) => setEditor((value) => ({ ...value, entityType: event.target.value as typeof editor.entityType }))}><option value="person">Person</option><option value="organization">Organization</option><option value="automated">Automated sender</option><option value="unknown">Needs review</option></select></label><label>Professional specialty<input value={editor.professionalSpecialty} onChange={(event) => setEditor((value) => ({ ...value, professionalSpecialty: event.target.value }))} placeholder="For example: Spanish law" /></label><label>Country or jurisdiction<input value={editor.jurisdiction} onChange={(event) => setEditor((value) => ({ ...value, jurisdiction: event.target.value }))} placeholder="For example: Spain" /></label><label>Relationship<select value={editor.relationshipType} onChange={(event) => setEditor((value) => ({ ...value, relationshipType: event.target.value }))}>{relationshipTypes.map((value) => <option key={value} value={value}>{relationshipLabels[value]}</option>)}</select></label><label>Your priority: {editor.manualPriority}/10<input type="range" min="1" max="10" value={editor.manualPriority} onChange={(event) => setEditor((value) => ({ ...value, manualPriority: Number(event.target.value) }))} /></label><label>Relationship summary<textarea value={editor.relationshipSummary} onChange={(event) => setEditor((value) => ({ ...value, relationshipSummary: event.target.value }))} placeholder="What matters in this relationship?" /></label><label>Private notes<textarea value={editor.notes} onChange={(event) => setEditor((value) => ({ ...value, notes: event.target.value }))} placeholder="Notes only you can see" /></label><button className="btn primary" disabled={saving} onClick={() => void save()}>{saving ? "Saving…" : "Save person"}</button>{message && <p className={message.startsWith("Person information saved") ? "positive" : "negative"}>{message}</p>}</div><div><div className="section-title">Verified identities</div>{selected.identities.length ? <div className="person-stack">{selected.identities.map((identity) => <div className="person-fact" key={identity.id}><strong>{identity.source}</strong><span>{identity.identifier}</span><small>{identity.verified ? "Verified match" : "Suggested match"}</small></div>)}</div> : <div className="empty-card">No connected identity.</div>}<div className="section-title">Verified memories</div>{selected.memories.length ? <div className="person-stack">{selected.memories.map((memory) => <div className="person-fact" key={memory.id}><strong>{memory.category}</strong><span>{memory.content}</span></div>)}</div> : <div className="empty-card">No memories approved by you yet.</div>}</div></div><div className="section-title">Relationship timeline</div>{selected.conversations.length ? <div className="timeline">{selected.conversations.map((conversation) => <div className="timeline-item" key={conversation.id}><div className="timeline-dot" /><div><strong>{conversation.title}</strong><span>{conversation.summary || "No summary yet."}</span><small>{conversation.source}{conversation.lastMessageAt ? ` · ${new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(conversation.lastMessageAt))}` : ""}</small></div></div>)}</div> : <div className="empty-card">No conversations connected to this person yet.</div>}</section> : <div className="empty-card">No people have been imported yet.</div>}</div></div>;
